-- ============================================================
--  Medialijst overnemen en samenvoegen
--
--  Uit "MCN Medialijst" (Klaas Smit): 132 organisaties, waarvan er
--  13 al in de relatielijst stonden. Gemaakt op 23 September 2026.
--
--  Draai dit ná 11 (soorten) en 12 (sectoren).
--
--  LET OP: elke organisatie staat hier als een eigen opdracht. Dat
--  is lang, maar het betekent dat een plak die halverwege afkapt
--  gewoon invoegt wat er wél aankwam. Draai het bestand daarna
--  nog eens en de rest komt erbij. Dubbelen kunnen niet ontstaan.
--
--  Onderaan staat een telling. Klopt die niet, plak dan opnieuw.
-- ============================================================

-- ── Sectoren ────────────────────────────────────────────────

-- ── Soorten ─────────────────────────────────────────────────

-- ── De organisaties (132) ────────────────────────────────────
-- Bestaat er al een, dan worden alleen lege velden aangevuld.

-- ── Controle: hier hoort 175 te staan ───────────────────────
select 'organisaties' as tabel, count(*) from organisaties
union all select 'waarvan met sector', count(*) from organisaties where sector <> ''
union all select 'waarvan met soort', count(*) from organisaties where soort <> ''
union all select 'sectoren in de keuzelijst', count(*) from organisatie_sectoren
union all select 'soorten in de keuzelijst', count(*) from organisatie_soorten;
